// Simulate splitting question into sub-questions
const question = $json["question"] || ($json.body && $json.body.question) || "default question";
return [{ json: { subQuestions: [
  `What is the process for ${question}?`,
  `What are the risks related to ${question}?`
]}}];

// Simulate routing based on metadata
const subQs = $json["subQuestions"] || [];
return subQs.map(q => ({ json: { domain: q.includes('risks') ? 'Risk Expert' : 'Process Expert', subQuestion: q }}));

// Simulate Supervisor review and final answer composition
const answers = $input.all().map(e => e.json.message?.content || e.json.answer || e.json.subQuestion + ' (simulated answer)').join('

');
return [{ json: { finalAnswer: `Based on expert analysis:

${answers}` }}];
